import React, { useState, useEffect } from "react";
import { Plus, Trash2, Edit3, X, Check, Shield, Lock, Monitor, Package, BarChart3, Users, Layout, Zap, AlertCircle } from "lucide-react";
import API_BASE from "../config";

const standardRoles = [
    "Manager / Admin",
    "Billing User / Cashier",
    "Captain / Steward",
    "Waiter / Server",
    "Kitchen Staff / Chef",
    "Delivery Boy",
    "Inventory Manager"
];

const DesignationManager = () => {
    const [designations, setDesignations] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingId, setEditingId] = useState(null);
    const [formData, setFormData] = useState({ name: standardRoles[0], is_active: true });
    const [confirmDeleteId, setConfirmDeleteId] = useState(null);

    const fetchDesignations = async () => {
        try {
            const res = await fetch(`${API_BASE}/api/brand/designations`, {
                headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
            });
            const data = await res.json();
            setDesignations(Array.isArray(data) ? data : []);
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    };

    useEffect(() => { fetchDesignations(); }, []);

    const handleSubmit = async (e) => {
        e.preventDefault();
        const method = editingId ? "PUT" : "POST";
        const url = editingId ? `${API_BASE}/api/brand/designations/${editingId}` : `${API_BASE}/api/brand/designations`;
        
        try {
            const res = await fetch(url, {
                method,
                headers: { 
                    "Content-Type": "application/json",
                    "Authorization": `Bearer ${localStorage.getItem("token")}`
                },
                body: JSON.stringify(formData)
            });
            if (res.ok) {
                alert("Matrix Updated Successfully!");
                setIsModalOpen(false);
                setEditingId(null);
                setFormData({ name: standardRoles[0], is_active: true });
                fetchDesignations();
            } else {
                const errData = await res.json();
                alert("Error: " + (errData.error || "Update Failed"));
            }
        } catch (e) { 
            console.error(e); 
            alert("System Error: Could not reach server.");
        }
    };

    const openEdit = (d) => {
        setEditingId(d.id);
        setFormData({ 
            name: d.name, 
            is_active: d.is_active !== false
        });
        setIsModalOpen(true);
    };

    const executeDelete = async () => {
        if (!confirmDeleteId) return;
        try {
            await fetch(`${API_BASE}/api/brand/designations/${confirmDeleteId}`, {
                method: "DELETE",
                headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
            });
            setConfirmDeleteId(null);
            fetchDesignations();
        } catch (e) { console.error(e); }
    };

    return (
        <div className="space-y-6 animate-pro-in">
            {/* Header Hub */}
            <div className="flex items-center justify-between bg-white dark:bg-[#1e2129] p-4 rounded-lg border border-slate-200 dark:border-white/5 shadow-sm">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-indigo-600/10 rounded flex items-center justify-center text-indigo-600">
                        <Users className="w-6 h-6" />
                    </div>
                    <div>
                        <h2 className="text-[14px] font-bold text-slate-800 dark:text-white uppercase tracking-tight">Designation Matrix</h2>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Enterprise Role Registry</p>
                    </div>
                </div>
                <button 
                    onClick={() => { setEditingId(null); setFormData({ name: standardRoles[0], isActive: true }); setIsModalOpen(true); }}
                    className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-[11px] font-bold uppercase tracking-widest transition-all flex items-center gap-2 shadow-md shadow-indigo-600/20"
                >
                    <Plus className="w-4 h-4" /> Add Designation
                </button>
            </div>

            {/* Main Grid */}
            <div className="bg-white dark:bg-[#1e2129] rounded-lg border border-slate-200 dark:border-white/5 overflow-hidden shadow-sm">
                <table className="w-full text-left">
                    <thead>
                        <tr className="bg-slate-50 dark:bg-black/20 border-b border-slate-200 dark:border-white/5">
                            <th className="px-6 py-4 text-[11px] font-bold text-slate-500 uppercase tracking-widest">Action</th>
                            <th className="px-6 py-4 text-[11px] font-bold text-slate-500 uppercase tracking-widest">#</th>
                            <th className="px-6 py-4 text-[11px] font-bold text-slate-800 dark:text-slate-200 uppercase tracking-widest">Designation Identity</th>
                            <th className="px-6 py-4 text-[11px] font-bold text-slate-500 uppercase tracking-widest text-right">Operational Status</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-white/5">
                        {loading ? (
                            <tr><td colSpan="4" className="py-20 text-center animate-pulse text-[11px] uppercase tracking-widest font-bold text-slate-400">Scanning Registry...</td></tr>
                        ) : designations.map((d, i) => (
                            <tr key={d.id} className="hover:bg-slate-50 dark:hover:bg-white/5 transition-colors">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-2">
                                        <button onClick={() => openEdit(d)} className="w-8 h-8 bg-slate-100 dark:bg-white/10 hover:bg-indigo-600 hover:text-white rounded flex items-center justify-center text-slate-400 transition-all"><Edit3 className="w-3.5 h-3.5" /></button>
                                        <button onClick={() => setConfirmDeleteId(d.id)} className="w-8 h-8 bg-rose-500/10 hover:bg-rose-600 rounded flex items-center justify-center text-rose-500 hover:text-white transition-all"><Trash2 className="w-3.5 h-3.5" /></button>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-[12px] font-bold text-slate-400">{i + 1}</td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-2">
                                        <div className="w-2 h-2 rounded-full bg-indigo-500" />
                                        <span className="text-[13px] font-bold text-slate-800 dark:text-white uppercase tracking-tight">{d.name}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <span className={`px-2 py-1 rounded text-[9px] font-bold uppercase tracking-widest ${d.is_active !== false ? 'bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600 dark:text-emerald-500 border border-emerald-200 dark:border-emerald-500/20' : 'bg-rose-50 dark:bg-rose-500/10 text-rose-600 dark:text-rose-500 border border-rose-200 dark:border-rose-500/20'}`}>
                                        {d.is_active !== false ? 'Active' : 'Disabled'}
                                    </span>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Action Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/40 backdrop-blur-md animate-in fade-in duration-200">
                    <form onSubmit={handleSubmit} className="bg-white dark:bg-[#1e2129] w-full max-w-md rounded-xl border border-slate-200 dark:border-white/10 shadow-2xl overflow-hidden">
                        <div className="p-4 bg-slate-50 dark:bg-black/20 border-b border-slate-200 dark:border-white/5 flex items-center justify-between">
                            <h3 className="text-[12px] font-bold text-slate-800 dark:text-white uppercase tracking-widest">{editingId ? "Update Role" : "Register New Role"}</h3>
                            <button type="button" onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><X className="w-5 h-5" /></button>
                        </div>
                        
                        <div className="p-6 space-y-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Select Designation</label>
                                <select 
                                    required
                                    value={formData.name}
                                    onChange={e => {
                                        const newName = e.target.value;
                                        setFormData(prev => ({ ...prev, name: newName }));
                                    }}
                                    className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-lg px-4 py-3 text-slate-900 dark:text-white outline-none focus:border-indigo-500 transition-all font-bold text-[12px] appearance-none cursor-pointer"
                                >
                                    {standardRoles.map(role => (
                                        <option key={role} value={role} className="bg-white dark:bg-[#1e2129] text-slate-900 dark:text-white font-bold">{role}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-black/20 rounded-lg border border-slate-100 dark:border-white/5">
                                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Active Status</span>
                                <label className="flex items-center gap-2 cursor-pointer group">
                                    <input 
                                        type="checkbox" 
                                        checked={formData.is_active}
                                        onChange={e => setFormData({...formData, is_active: e.target.checked})}
                                        className="hidden"
                                    />
                                    <div className={`w-10 h-5 rounded-full relative transition-all ${formData.is_active ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-white/10'}`}>
                                        <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${formData.is_active ? 'right-1' : 'left-1'}`} />
                                    </div>
                                </label>
                            </div>
                        </div>

                        <div className="p-4 bg-slate-50 dark:bg-black/20 border-t border-slate-200 dark:border-white/5 flex gap-3">
                            <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-2 text-[11px] font-bold text-slate-400 hover:text-slate-600 dark:hover:text-white uppercase tracking-widest transition-all">Abort</button>
                            <button type="submit" className="flex-[2] py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-[11px] font-bold uppercase tracking-widest transition-all shadow-xl shadow-indigo-600/20">
                                {editingId ? "Confirm Update" : "Establish Role"}
                            </button>
                        </div>
                    </form>
                </div>
            )}

            {/* Custom Delete Dialogue */}
            {confirmDeleteId && (
                <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/40 backdrop-blur-md animate-in fade-in duration-200">
                    <div className="bg-white dark:bg-[#1e2129] w-full max-w-xs rounded-xl overflow-hidden shadow-2xl border border-slate-200 dark:border-white/5 p-8 text-center">
                        <div className="w-14 h-14 bg-rose-500/10 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner"><AlertCircle className="w-8 h-8" /></div>
                        <h4 className="text-[14px] font-bold text-slate-800 dark:text-white uppercase tracking-tight mb-8 leading-tight">Terminate this designation?</h4>
                        <div className="flex gap-4">
                            <button onClick={() => setConfirmDeleteId(null)} className="flex-1 py-3 bg-slate-100 dark:bg-white/5 text-slate-500 dark:text-slate-400 rounded-lg text-[10px] font-bold uppercase tracking-widest hover:bg-slate-200 dark:hover:bg-white/10 transition-all">Abort</button>
                            <button onClick={executeDelete} className="flex-[2] py-3 bg-rose-600 text-white rounded-lg text-[10px] font-bold uppercase tracking-widest hover:bg-rose-500 transition-all shadow-xl shadow-rose-600/20">Confirm</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default DesignationManager;

